export const MEMORY_MATCH_HTML =
  "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\">\n<title>Memory Match</title>\n<!--\n  Ally course component: GAME / MEMORY_MATCH.\n\n  A 4x4 deck of eight pairs. Flip two cards; if the icons match they stay up.\n  Adapted from the \"Sweet Memory Game\" pen by Elior Tabeka\n  (https://codepen.io/eliortabeka/pen/WwzEEg) — the rules, the move counter and\n  the three-star rating are its design. Nothing else survives the port: the\n  original leaned on jQuery, FontAwesome, SweetAlert2, animate.css and a Google\n  font, and a bundle here has to run from an opaque origin with no network (the\n  mobile app inlines this file into a WebView so a course works offline), so\n  the markup, styles and logic below are hand-written vanilla against the Ally\n  palette.\n\n  This page is loaded in a sandboxed iframe by GameItemPlayer and in a WebView\n  by the mobile GamePlayer, and talks to either only through postMessage — see\n  the bridge at the bottom of this file for the contract.\n-->\n<style>\n/*\n  Ally tokens, copied as literals.\n\n  The host's palette lives in CSS variables on its own document; a sandboxed\n  iframe cannot see them, and the mobile WebView has no host document at all.\n  These are the daylight (default) theme's values from the helpline app's\n  index.css. A learner on another theme gets Ally blue rather than their theme's\n  accent, which is the same trade the T-Rex bundle makes by being Chromium grey.\n*/\n:root {\n  --primary-50: #EBF0FA;\n  --primary-100: #D7E2F4;\n  --primary-400: #4A7DCF;\n  --primary-500: #264D8E;\n  --primary-600: #1F3F75;\n\n  --success-50: #E8F5E9;\n  --success-200: #A5D6A7;\n  --success-700: #388E3C;\n\n  --destructive-50: #FFCDD2;\n  --destructive-400: #F93535;\n  --destructive-600: #C71818;\n\n  --background: #FFFFFF;\n  --background-secondary: #F4F4F4;\n  --border-light: #E0E0E0;\n  --border-medium: #C6C6C6;\n\n  --typography-500: rgba(0, 0, 0, 0.32);\n  --typography-700: rgba(0, 0, 0, 0.54);\n  --typography-900: rgba(0, 0, 0, 0.87);\n\n  /*\n    IBM Plex Serif is Ally's face but it is served by the host app, and a font\n    fetched from an opaque origin (or from an inlined WebView document) will not\n    load. Georgia is the closest serif every target platform already has.\n  */\n  --font: \"IBM Plex Serif\", Georgia, \"Times New Roman\", serif;\n\n  /*\n    One square deck that fits whatever frame the host gives us. The host picks\n    the frame height; this keeps the board square inside it either way.\n    84px is the score panel plus the page's own padding.\n  */\n  --deck: min(calc(100vw - 24px), calc(100vh - 84px), 420px);\n  --gap: clamp(5px, 2.2%, 11px);\n}\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  height: 100%;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background: var(--background);\n  color: var(--typography-900);\n  font-family: var(--font);\n  font-size: 14px;\n  line-height: 24px;\n  overflow: hidden;\n  -webkit-user-select: none;\n  user-select: none;\n  -webkit-tap-highlight-color: transparent;\n}\n\n.game {\n  height: 100%;\n  padding: 12px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n}\n\n/* ---- Score panel ------------------------------------------------------- */\n\n.panel {\n  width: var(--deck);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n/* Pairs found, as pips. A count of eight dots reads without a label, which\n   matters because this page carries no prose the host could translate. */\n.pairs {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  flex: 1;\n  min-width: 0;\n}\n\n.pip {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--border-light);\n  transition: background 0.2s ease, transform 0.2s ease;\n}\n\n.pip.filled {\n  background: var(--success-700);\n  transform: scale(1.15);\n}\n\n.moves {\n  color: var(--typography-700);\n  font-size: 13px;\n  white-space: nowrap;\n}\n\n\n.stars {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n  color: var(--primary-500);\n}\n\n.star { width: 16px; height: 16px; display: block; }\n.star.off { color: var(--border-light); }\n\n.icon-button {\n  appearance: none;\n  border: 1px solid var(--border-light);\n  background: var(--background);\n  color: var(--typography-700);\n  border-radius: 8px;\n  width: 30px;\n  height: 30px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  cursor: pointer;\n  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;\n}\n\n.icon-button:hover {\n  background: var(--primary-50);\n  border-color: var(--primary-100);\n  color: var(--primary-500);\n}\n\n.icon-button svg { width: 15px; height: 15px; display: block; }\n\n/* ---- Deck -------------------------------------------------------------- */\n\n.deck {\n  width: var(--deck);\n  height: var(--deck);\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  grid-template-rows: repeat(4, 1fr);\n  gap: var(--gap);\n  perspective: 900px;\n}\n\n.card {\n  appearance: none;\n  border: 0;\n  padding: 0;\n  background: none;\n  position: relative;\n  cursor: pointer;\n  transform: rotateY(180deg);\n  transform-style: preserve-3d;\n  transition: transform 0.28s ease;\n}\n\n.card.face-up { transform: rotateY(0deg); }\n\n.card:disabled { cursor: default; }\n\n/* Keyboard focus has to sit on the card, not a face, or the ring flips away\n   with the card and a keyboard learner loses their place. */\n.card:focus-visible {\n  outline: 2px solid var(--primary-400);\n  outline-offset: 2px;\n  border-radius: 10px;\n}\n\n.face {\n  position: absolute;\n  inset: 0;\n  border-radius: 10px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  backface-visibility: hidden;\n  -webkit-backface-visibility: hidden;\n}\n\n/* Face down: solid Ally blue, no icon to read. */\n.back {\n  transform: rotateY(180deg);\n  background: var(--primary-500);\n  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.12);\n  transition: background 0.15s ease;\n}\n\n.card:not(:disabled):hover .back { background: var(--primary-600); }\n\n/* Face up and still being judged. */\n.front {\n  background: var(--background);\n  border: 2px solid var(--primary-400);\n  color: var(--primary-500);\n}\n\n.front svg {\n  width: 46%;\n  height: 46%;\n  display: block;\n}\n\n.card.matched .front {\n  background: var(--success-50);\n  border-color: var(--success-200);\n  color: var(--success-700);\n}\n\n.card.wrong .front {\n  background: var(--destructive-50);\n  border-color: var(--destructive-400);\n  color: var(--destructive-600);\n}\n\n.card.matched { animation: pop 0.4s ease; }\n.card.wrong { animation: shake 0.4s ease; }\n\n@keyframes pop {\n  0%, 100% { transform: rotateY(0deg) scale(1); }\n  45% { transform: rotateY(0deg) scale(1.09); }\n}\n\n@keyframes shake {\n  0%, 100% { transform: rotateY(0deg) translateX(0); }\n  20% { transform: rotateY(0deg) translateX(-5px); }\n  50% { transform: rotateY(0deg) translateX(5px); }\n  80% { transform: rotateY(0deg) translateX(-3px); }\n}\n\n/* A learner who has asked for less motion still needs to see the flip, so the\n   card turn stays — only the celebratory jiggle goes. */\n@media (prefers-reduced-motion: reduce) {\n  .card.matched, .card.wrong { animation: none; }\n}\n\n/* ---- End-of-round overlay ---------------------------------------------- */\n\n.overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(255, 255, 255, 0.86);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 16px;\n}\n\n.overlay[hidden] { display: none; }\n\n.dialog {\n  background: var(--background);\n  border: 1px solid var(--border-light);\n  border-radius: 12px;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);\n  padding: 20px;\n  max-width: 300px;\n  text-align: center;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n}\n\n.dialog .stars { gap: 4px; }\n.dialog .star { width: 24px; height: 24px; }\n\n.dialog h1 {\n  margin: 0;\n  font-size: 16px;\n  line-height: 28px;\n  font-weight: 600;\n  color: var(--typography-900);\n}\n\n.dialog p {\n  margin: 0;\n  font-size: 13px;\n  line-height: 20px;\n  color: var(--typography-700);\n}\n\n.button {\n  appearance: none;\n  margin-top: 6px;\n  border: 0;\n  border-radius: 8px;\n  background: var(--primary-500);\n  color: #FFFFFF;\n  font-family: inherit;\n  font-size: 14px;\n  line-height: 24px;\n  padding: 6px 20px;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.button:hover { background: var(--primary-600); }\n\n.button:focus-visible {\n  outline: 2px solid var(--primary-400);\n  outline-offset: 2px;\n}\n</style>\n</head>\n<body>\n\n<main class=\"game\">\n  <div class=\"panel\">\n    <div class=\"pairs\" id=\"pairs\" aria-hidden=\"true\"></div>\n    <p class=\"moves\" id=\"moves\"></p>\n    <div class=\"stars\" id=\"stars\" aria-hidden=\"true\"></div>\n    <button type=\"button\" class=\"icon-button\" id=\"restart\"></button>\n  </div>\n\n  <div class=\"deck\" id=\"deck\"></div>\n</main>\n\n<div class=\"overlay\" id=\"overlay\" hidden>\n  <div class=\"dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"won-title\">\n    <div class=\"stars\" id=\"won-stars\" aria-hidden=\"true\"></div>\n    <h1 id=\"won-title\"></h1>\n    <p id=\"won-detail\"></p>\n    <button type=\"button\" class=\"button\" id=\"play-again\"></button>\n  </div>\n</div>\n\n<script>\n(function () {\n  'use strict';\n\n  /* ---- Copy ------------------------------------------------------------ */\n\n  /**\n   * Everything a learner reads here. Baked in English and overridden by the\n   * host, which is the side that knows their language: the web app sends these\n   * with its `focus` message, the mobile app sets `window.__allyGameStrings`\n   * before this document loads. English is the fallback either way, so a host\n   * that sends nothing still gets a working game.\n   */\n  var STRINGS = {\n    moves: '{{moves}} moves',\n    restart: 'Start over',\n    wonTitle: 'Board cleared',\n    wonDetail: '{{moves}} moves — {{score}}% of a perfect round',\n    playAgain: 'Play again',\n    cardLabel: 'Card {{number}}'\n  };\n\n  if (window.__allyGameStrings) applyStrings(window.__allyGameStrings);\n\n  function applyStrings(next) {\n    for (var key in STRINGS) {\n      if (Object.prototype.hasOwnProperty.call(next, key) &&\n          typeof next[key] === 'string') {\n        STRINGS[key] = next[key];\n      }\n    }\n  }\n\n  function fill(template, values) {\n    return template.replace(/{{(\\w+)}}/g, function (whole, name) {\n      return Object.prototype.hasOwnProperty.call(values, name)\n        ? String(values[name])\n        : whole;\n    });\n  }\n\n  /* ---- Icons ----------------------------------------------------------- */\n\n  function svg(body, filled) {\n    return '<svg viewBox=\"0 0 24 24\" fill=\"' + (filled ? 'currentColor' : 'none') +\n      '\" stroke=\"' + (filled ? 'none' : 'currentColor') +\n      '\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"' +\n      ' focusable=\"false\" aria-hidden=\"true\">' + body + '</svg>';\n  }\n\n  var STAR_PATH = '<path d=\"M12 2.6l3 6.1 6.7 1-4.9 4.7 1.2 6.7L12 17.9l-6 3.2 1.2-6.7L2.3 9.7l6.7-1z\"/>';\n\n  /**\n   * The eight pairs. Deliberately eight shapes that stay apart at a glance and\n   * at 30px — a deck of near-identical glyphs turns a memory game into an\n   * eyesight test.\n   */\n  var SYMBOLS = [\n    '<path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 1 0-7.8 7.8L12 21.2l8.8-8.8a5.5 5.5 0 0 0 0-7.8z\"/>',\n    '<path d=\"M12 2.5l8.5 4.9v9.2L12 21.5 3.5 16.6V7.4z\"/><path d=\"M3.7 7.4L12 12.2l8.3-4.8\"/><path d=\"M12 21.5v-9.3\"/>',\n    '<path d=\"M13 2L4.1 12.8h6.4L11 22l8.9-10.8h-6.4z\"/>',\n    '<path d=\"M11 20a7 7 0 0 1-7-7c0-6 8-9 16-9 0 8-3 16-9 16z\"/><path d=\"M4 21c2-6 5-9 9-11\"/>',\n    '<circle cx=\"12\" cy=\"5\" r=\"3\"/><path d=\"M12 22V8\"/><path d=\"M5 12H2a10 10 0 0 0 20 0h-3\"/>',\n    '<path d=\"M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z\"/>',\n    '<path d=\"M12 2.7L6.3 8.4a8 8 0 1 0 11.4 0z\"/>',\n    '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M16.2 7.8l-2.9 6.4-6.4 2.9 2.9-6.4z\"/>'\n  ];\n\n  var RESTART_ICON = svg('<path d=\"M3 12a9 9 0 1 0 3-6.7\"/><path d=\"M3 4v5h5\"/>');\n\n  /* ---- Rules ----------------------------------------------------------- */\n\n  var PAIRS = SYMBOLS.length;\n  /** A round in which every flip lands a pair: one move per pair. */\n  var PERFECT_MOVES = PAIRS;\n  /** Moves you can spend and still keep 3, 2 and 1 star, from the original. */\n  var STAR_THRESHOLDS = [PAIRS + 2, PAIRS + 6, PAIRS + 10];\n  /** How long a mismatched pair stays visible before flipping back. */\n  var REVEAL_MS = 800;\n\n  var deckEl = document.getElementById('deck');\n  var pairsEl = document.getElementById('pairs');\n  var movesEl = document.getElementById('moves');\n  var starsEl = document.getElementById('stars');\n  var restartEl = document.getElementById('restart');\n  var overlayEl = document.getElementById('overlay');\n  var wonStarsEl = document.getElementById('won-stars');\n  var wonTitleEl = document.getElementById('won-title');\n  var wonDetailEl = document.getElementById('won-detail');\n  var playAgainEl = document.getElementById('play-again');\n\n  var cards = [];\n  var opened = [];\n  var matched = 0;\n  var moves = 0;\n  var locked = false;\n  var sessionBest = 0;\n  var pendingTimers = [];\n\n  /** Fisher-Yates. */\n  function shuffle(array) {\n    for (var i = array.length - 1; i > 0; i--) {\n      var j = Math.floor(Math.random() * (i + 1));\n      var swap = array[i];\n      array[i] = array[j];\n      array[j] = swap;\n    }\n    return array;\n  }\n\n  function starsFor(moveCount) {\n    for (var i = 0; i < STAR_THRESHOLDS.length; i++) {\n      if (moveCount <= STAR_THRESHOLDS[i]) return 3 - i;\n    }\n    return 0;\n  }\n\n  /**\n   * The number the host records as a personal best, so it has to climb with\n   * good play — moves do the opposite. This is how close the round came to a\n   * perfect eight-move clear, which is the thing the game actually measures.\n   */\n  function scoreFor(moveCount) {\n    if (!moveCount) return 0;\n    return Math.min(100, Math.round((PERFECT_MOVES / moveCount) * 100));\n  }\n\n  function renderStars(target, count) {\n    var html = '';\n    for (var i = 0; i < 3; i++) {\n      html += '<span class=\"star' + (i < count ? '' : ' off') + '\">' +\n        svg(STAR_PATH, true) + '</span>';\n    }\n    target.innerHTML = html;\n  }\n\n  function renderPanel() {\n    var pips = '';\n    for (var i = 0; i < PAIRS; i++) {\n      pips += '<span class=\"pip' + (i < matched ? ' filled' : '') + '\"></span>';\n    }\n    pairsEl.innerHTML = pips;\n    movesEl.textContent = fill(STRINGS.moves, { moves: moves });\n    renderStars(starsEl, starsFor(moves));\n    restartEl.innerHTML = RESTART_ICON;\n    restartEl.setAttribute('aria-label', STRINGS.restart);\n    restartEl.setAttribute('title', STRINGS.restart);\n    playAgainEl.textContent = STRINGS.playAgain;\n  }\n\n  function clearTimers() {\n    pendingTimers.forEach(clearTimeout);\n    pendingTimers = [];\n  }\n\n  function later(fn, ms) {\n    pendingTimers.push(setTimeout(fn, ms));\n  }\n\n  function newRound() {\n    clearTimers();\n    overlayEl.hidden = true;\n    deckEl.innerHTML = '';\n    cards = [];\n    opened = [];\n    matched = 0;\n    moves = 0;\n    locked = false;\n    announcedStart = false;\n\n    var order = shuffle(SYMBOLS.concat(SYMBOLS).map(function (icon, index) {\n      return { icon: icon, symbol: index % PAIRS };\n    }));\n\n    order.forEach(function (entry, index) {\n      var card = document.createElement('button');\n      card.type = 'button';\n      card.className = 'card';\n      card.setAttribute('aria-label', fill(STRINGS.cardLabel, { number: index + 1 }));\n      card.innerHTML = '<span class=\"face back\"></span>' +\n        '<span class=\"face front\">' + svg(entry.icon) + '</span>';\n      card.addEventListener('click', function () { flip(card); });\n      card.allySymbol = entry.symbol;\n      deckEl.appendChild(card);\n      cards.push(card);\n    });\n\n    renderPanel();\n  }\n\n  function flip(card) {\n    if (locked || card.disabled || card.classList.contains('face-up')) return;\n\n    markStarted();\n    card.classList.add('face-up');\n    opened.push(card);\n    if (opened.length < 2) return;\n\n    moves++;\n    var first = opened[0];\n    var second = opened[1];\n    opened = [];\n\n    if (first.allySymbol === second.allySymbol) {\n      matched++;\n      [first, second].forEach(function (el) {\n        el.classList.add('matched');\n        el.disabled = true;\n      });\n      renderPanel();\n      if (matched === PAIRS) later(finish, 450);\n      return;\n    }\n\n    // Both wrong cards stay readable for a beat — the whole point of the game\n    // is getting a look at where they were — so the board is locked until they\n    // turn back rather than letting a fast tap start a third card mid-flip.\n    locked = true;\n    first.classList.add('wrong');\n    second.classList.add('wrong');\n    renderPanel();\n    later(function () {\n      [first, second].forEach(function (el) {\n        el.classList.remove('face-up', 'wrong');\n      });\n      locked = false;\n    }, REVEAL_MS);\n  }\n\n  function finish() {\n    var score = scoreFor(moves);\n    sessionBest = Math.max(sessionBest, score);\n    renderStars(wonStarsEl, starsFor(moves));\n    wonTitleEl.textContent = STRINGS.wonTitle;\n    wonDetailEl.textContent = fill(STRINGS.wonDetail, { moves: moves, score: score });\n    overlayEl.hidden = false;\n    playAgainEl.focus();\n    post('over', { score: score, highScore: sessionBest });\n  }\n\n  restartEl.addEventListener('click', newRound);\n  playAgainEl.addEventListener('click', newRound);\n\n  /* ---- Host bridge ------------------------------------------------------ */\n\n  /**\n   * [Ally] Host bridge — the whole contract between a game bundle and the app.\n   *\n   * A game folder under /games/<key>/ is a self-contained page. It never\n   * imports from the app and the app never reaches into it; they exchange\n   * three messages. The same file runs in two hosts: an <iframe> in the web app\n   * (messages go to window.parent) and a react-native-webview in the mobile app\n   * (messages go to window.ReactNativeWebView as a JSON string).\n   *\n   *   game -> host  { source:'ally-game', game, type:'ready' }\n   *   game -> host  { source:'ally-game', game, type:'started' }\n   *   game -> host  { source:'ally-game', game, type:'over', score, highScore }\n   *\n   *   host -> game  { source:'ally-game-host', type:'focus', strings? }\n   *\n   * Scores are reported for the learner's personal best only. Games in a course\n   * never gate progression, so nothing here blocks, unlocks or grades anything.\n   */\n  var GAME = 'MEMORY_MATCH';\n  var iframeHost = window.parent !== window ? window.parent : null;\n\n  function post(type, extra) {\n    var message = { source: 'ally-game', game: GAME, type: type };\n    for (var key in extra) {\n      if (Object.prototype.hasOwnProperty.call(extra, key)) message[key] = extra[key];\n    }\n    if (window.ReactNativeWebView) {\n      // WebView bridge only speaks strings.\n      window.ReactNativeWebView.postMessage(JSON.stringify(message));\n      return;\n    }\n    // '*' because a sandboxed iframe has an opaque origin that matches no\n    // concrete target. Nothing here is worth protecting from the parent.\n    if (iframeHost) iframeHost.postMessage(message, '*');\n  }\n\n  var announcedStart = false;\n  function markStarted() {\n    if (announcedStart) return;\n    announcedStart = true;\n    post('started');\n  }\n\n  window.addEventListener('message', function (event) {\n    var data = event.data;\n    if (!data || data.source !== 'ally-game-host') return;\n    if (data.strings) {\n      applyStrings(data.strings);\n      // Labels are already on screen by the time this lands, so redraw them\n      // rather than waiting for the next move.\n      cards.forEach(function (card, index) {\n        card.setAttribute('aria-label', fill(STRINGS.cardLabel, { number: index + 1 }));\n      });\n      renderPanel();\n    }\n    if (data.type === 'focus') window.focus();\n  });\n\n  newRound();\n  post('ready');\n})();\n</script>\n</body>\n</html>\n";
